cat > /etc/nginx/sites-available/default << 'EOF'
server {
    listen 8443 ssl;
    server_name localhost;

    ssl_certificate /etc/nginx/ssl/nginx.crt;
    ssl_certificate_key /etc/nginx/ssl/nginx.key;

    location / {
        root /var/www/main;
        index index.html;
    }

    location /dev {
        alias /var/www/dev;
        index index.html;
    }
}
EOF

